-- Function: public.sp_update_admin_user
-- Backup generated on 2026-11-11 09:06:00

CREATE OR REPLACE PROCEDURE public.sp_update_admin_user(IN p_user_id uuid, IN p_email character varying, IN p_first_name character varying, IN p_last_name character varying, IN p_password character varying, IN p_role_name character varying, IN p_account_status character varying, IN p_org_id uuid DEFAULT NULL::uuid)  LANGUAGE plpgsql AS $procedure$ DECLARE     v_clean_email character varying;     v_old_is_platform_admin boolean;     v_new_is_platform_admin boolean;     v_platform_admin_count integer;     v_platform_role_id uuid;     v_target_role_id uuid;     v_tenant_id uuid;     v_is_active boolean; BEGIN     v_clean_email := lower(trim(p_email));     v_is_active := (lower(trim(p_account_status)) = 'active');          SELECT id INTO v_platform_role_id FROM roles WHERE name = 'PlatformAdmin' LIMIT 1;      -- Check if user currently has platform admin role     SELECT EXISTS (         SELECT 1 FROM user_roles          WHERE user_id = p_user_id            AND role_id IN (SELECT id FROM roles WHERE name IN ('PlatformAdmin', 'SuperAdmin'))     ) INTO v_old_is_platform_admin;      v_new_is_platform_admin := (p_role_name IN ('PlatformAdmin', 'SuperAdmin'));      -- If promoting to platform admin from a non-platform admin role, check limit of 3     IF v_new_is_platform_admin AND NOT v_old_is_platform_admin THEN         SELECT COUNT(DISTINCT ur.user_id) INTO v_platform_admin_count         FROM user_roles ur         JOIN roles r ON ur.role_id = r.id         WHERE r.name IN ('PlatformAdmin', 'SuperAdmin');          IF v_platform_admin_count >= 3 THEN             RAISE EXCEPTION 'A maximum of 3 platform administrators can exist at any point in time. Please remove an existing platform administrator before promoting a new one.';         END IF;     END IF;      -- If demoting from platform admin to an org role, ensure not the last one     IF v_old_is_platform_admin AND NOT v_new_is_platform_admin THEN         SELECT COUNT(DISTINCT ur.user_id) INTO v_platform_admin_count         FROM user_roles ur         JOIN roles r ON ur.role_id = r.id         WHERE r.name IN ('PlatformAdmin', 'SuperAdmin');          IF v_platform_admin_count <= 1 THEN             RAISE EXCEPTION 'Cannot demote the only remaining platform administrator. At least one platform administrator must exist.';         END IF;     END IF;      -- Update users table     UPDATE users      SET email = v_clean_email,         normalized_email = upper(v_clean_email),         first_name = p_first_name,         last_name = p_last_name,         display_name = trim(concat(p_first_name, ' ', p_last_name)),         is_active = v_is_active,         password_hash = CASE WHEN p_password IS NOT NULL AND trim(p_password) != '' THEN p_password ELSE password_hash END,         updated_at = NOW()     WHERE id = p_user_id;      -- Handle role transitions     IF v_new_is_platform_admin THEN         IF v_platform_role_id IS NOT NULL THEN             INSERT INTO user_roles (user_id, role_id)             VALUES (p_user_id, v_platform_role_id)             ON CONFLICT DO NOTHING;         END IF;     ELSE         -- Remove platform admin role if previously held         IF v_platform_role_id IS NOT NULL THEN             DELETE FROM user_roles WHERE user_id = p_user_id AND role_id = v_platform_role_id;         END IF;          -- Assign target organization role         IF p_org_id IS NOT NULL THEN             SELECT tenant_id INTO v_tenant_id FROM organizations WHERE id = p_org_id;             IF v_tenant_id IS NULL THEN v_tenant_id := p_org_id; END IF;              SELECT id INTO v_target_role_id              FROM roles              WHERE name = p_role_name                AND (tenant_id = p_org_id OR tenant_id IS NULL)             ORDER BY tenant_id NULLS LAST              LIMIT 1;              INSERT INTO organization_memberships (user_id, organization_id, tenant_id, status)             VALUES (p_user_id, p_org_id, v_tenant_id, p_account_status)             ON CONFLICT (user_id, organization_id) DO UPDATE SET status = p_account_status;              IF v_target_role_id IS NOT NULL THEN                 INSERT INTO user_organization_roles (user_id, role_id, organization_id, tenant_id)                 VALUES (p_user_id, v_target_role_id, p_org_id, v_tenant_id)                 ON CONFLICT (user_id, role_id, organization_id) DO NOTHING;                  INSERT INTO user_roles (user_id, role_id)                 VALUES (p_user_id, v_target_role_id)                 ON CONFLICT DO NOTHING;             END IF;         END IF;     END IF; END; $procedure$ ;
